16	declare_lint_rule! {
17	    /// Prefer using a type parameter over a type assertion on the initial value of `reduce`.
18	    ///
19	    /// When the initial value of an `Array#reduce` or `Array#reduceRight` call uses a type
20	    /// assertion (`as Type` or `<Type>expr`), TypeScript no longer checks that the reducer
21	    /// callback returns a compatible type. This can hide type mismatches. Passing the type as a
22	    /// type parameter on the call instead keeps that check in place.
23	    ///
24	    /// ## Examples
25	    ///
26	    /// ### Invalid
27	    ///
28	    /// ```ts,expect_diagnostic
29	    /// [1, 2, 3].reduce((acc, n) => [...acc, n], [] as number[]);
30	    /// ```
31	    ///
32	    /// ```ts,expect_diagnostic
33	    /// [1, 2, 3].reduceRight((acc, n) => [...acc, n], <number[]>[]);
34	    /// ```
35	    ///
36	    /// ### Valid
37	    ///
38	    /// ```ts
39	    /// [1, 2, 3].reduce<number[]>((acc, n) => [...acc, n], []);
40	    /// ```
41	    ///
42	    /// ```ts
43	    /// [1, 2, 3].reduce((acc, n) => acc + n, 0);
44	    /// ```
45	    ///
